// Complete localized editions follow the same evidence boundaries and section order.
// They intentionally use compact prose so every language remains maintainable as listings change.
type LocalePack = {
  reviewed: string;
  articles: Array<Omit<LocalizedArticle, "reviewedAt">>;
};

const buildLocalized = (pack: LocalePack): LocalizedArticle[] => pack.articles.map((article) => ({ ...article, reviewedAt: pack.reviewed }));

const section = (id: string, heading: string, ...paragraphs: string[]): SeoSection => ({ id, heading, paragraphs });

const localized = (
  id: string,
  tag: string,
  title: string,
  standfirst: string,
  summary: string,
  evidenceNote: string,
  facts: Array<[string, string]>,
  sections: SeoSection[],
): Omit<LocalizedArticle, "reviewedAt"> => {
  const source = en.find((article) => article.id === id)!;
  const { reviewedAt: _reviewedAt, ...base } = source;
  return { ...base, tag, title, standfirst, summary, evidenceNote, facts, sections };
};

